#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<long long> cum_sums(51, 0);
    cum_sums[0] = 1;
    for (int i = 1; i < 51; ++i) {
        cum_sums[i] = cum_sums[i - 1] + (1LL << i);
    }

    int h, n;
    cin >> h >> n;

    n += cum_sums[h - 1];
    vector<long long> sequence;
    sequence.push_back(n);
    while (n != 1) {
        n /= 2;
        sequence.push_back(n);
    }

    long long total_moves = 0;
    long long current = 1;
    bool flip_bit = false;

    while (current != sequence[0]) {
        vector<long long> temp_seq;
        long long temp_node = current;
        for (int i = 0; i < h; ++i) {
            temp_seq.push_back(temp_node);
            if (!flip_bit) {
                temp_node *= 2;
            } else {
                temp_node = temp_node * 2 + 1;
            }
            flip_bit = !flip_bit;
        }
        if (temp_node == sequence[0]) {
            total_moves += h;
            break;
        }
        temp_seq.push_back(temp_node);
        std::reverse(temp_seq.begin(), temp_seq.end());
        for (int i = 1; i <= h; ++i) {
            if (sequence[i] == temp_seq[i]) {
                total_moves += cum_sums[i - 1] + h - i + 1;
                h = i - 1;
                current = temp_seq[i - 1];
                if (current == temp_seq[i] * 2) {
                    current = temp_seq[i] * 2 + 1;
                    flip_bit = false;
                } else {
                    current = temp_seq[i] * 2;
                    flip_bit = true;
                }
                break;
            }
        }
    }
    cout << total_moves << "\n";
    return 0;
}
